//! Fixture-only adapter for the current Rust DTOs and TUI state.
//! Expectations are authored in JSON, never generated by this checker.

use std::{collections::BTreeMap, env, fs};

use crew_core::rpc::{ServerFrame, Snapshot, PROTOCOL_VERSION};
use crew_tui::App;
use serde_json::{json, Value};

fn subset(actual: &Value, expected: &Value, path: &str) {
    match expected {
        Value::Object(fields) => {
            let object = actual
                .as_object()
                .unwrap_or_else(|| panic!("{path}: not an object"));
            for (key, value) in fields {
                let field = object
                    .get(key)
                    .unwrap_or_else(|| panic!("{path}.{key}: missing"));
                subset(field, value, &format!("{path}.{key}"));
            }
        }
        Value::Array(values) => {
            let array = actual
                .as_array()
                .unwrap_or_else(|| panic!("{path}: not an array"));
            assert_eq!(array.len(), values.len(), "{path}: array length");
            for (index, (a, e)) in array.iter().zip(values).enumerate() {
                subset(a, e, &format!("{path}[{index}]"));
            }
        }
        _ => assert_eq!(actual, expected, "{path}"),
    }
}

fn observation(app: &App, expected: &Value, at: i64) -> Value {
    let mut agent_ids: Vec<_> = app.agents.iter().map(|a| a.id.as_str()).collect();
    agent_ids.sort_unstable();
    let agents: BTreeMap<_, _> = app.agents.iter().map(|a| (&a.id, a)).collect();
    let tasks: BTreeMap<_, _> = app.tasks.iter().map(|t| (&t.id, t)).collect();
    let mut work = BTreeMap::new();
    if let Some(queries) = expected.get("work").and_then(Value::as_object) {
        for id in queries.keys() {
            let actual = app.work_of(id, at).map(|w| {
                // The TUI exposes a title. These fixtures use unique titles,
                // so the adapter can recover identity without choosing work.
                let matching: Vec<_> = app.tasks.iter().filter(|t| t.title == w.title).collect();
                assert_eq!(matching.len(), 1, "fixture task titles must be unique");
                json!({"task_id": matching[0].id, "done": w.done, "elapsed_ms": w.elapsed})
            });
            work.insert(id.clone(), actual);
        }
    }
    let selections: Vec<_> = expected
        .get("selection_validity")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|query| {
            let id = query["id"].as_str().expect("selection id");
            let exists = match query["kind"].as_str().expect("selection kind") {
                "agent" => app.agents.iter().any(|a| a.id == id),
                "task" => app.tasks.iter().any(|t| t.id == id),
                other => panic!("unknown selection kind: {other}"),
            };
            json!({"kind": query["kind"], "id": id, "exists": exists})
        })
        .collect();
    json!({
        "agent_ids": agent_ids,
        "task_ids": app.tasks.iter().map(|t| &t.id).collect::<Vec<_>>(),
        "agents": agents,
        "tasks": tasks,
        "work": work,
        "message_ids": app.messages.iter().map(|m| &m.id).collect::<Vec<_>>(),
        "messages": app.messages,
        "event_seqs": app.events.iter().map(|e| e.seq).collect::<Vec<_>>(),
        "events": app.events,
        "question_ids": app.questions.iter().map(|q| &q.id).collect::<Vec<_>>(),
        "selection_validity": selections,
        "clock_offset_ms": app.clock_offset,
    })
}

fn main() {
    let mut total = 0;
    let mut cases = 0;
    for file in env::args().skip(1) {
        let case: Value = serde_json::from_str(&fs::read_to_string(&file).expect("read case"))
            .expect("case JSON");
        assert_eq!(case["schema_version"], 1, "{file}: schema version");
        assert_eq!(
            case["protocol"], PROTOCOL_VERSION,
            "{file}: protocol version"
        );
        let id = case["id"].as_str().expect("case id");
        let steps = case["steps"].as_array().expect("case steps");
        assert!(!steps.is_empty(), "{id}: no steps");
        assert!(
            steps[0].get("snapshot").is_some(),
            "{id}: first step must be a snapshot"
        );
        let mut app = App::new();
        for (index, step) in steps.iter().enumerate() {
            let at = step["at_ms"].as_i64().expect("integer at_ms");
            assert_ne!(
                step.get("snapshot").is_some(),
                step.get("frame").is_some(),
                "{id}/{index}: exactly one input"
            );
            if let Some(snapshot) = step.get("snapshot") {
                let decoded: Snapshot =
                    serde_json::from_value(snapshot.clone()).expect("Rust Snapshot DTO");
                let encoded = serde_json::to_value(&decoded).expect("serialize Snapshot");
                subset(
                    &encoded,
                    snapshot,
                    &format!("{id}/{index}: wire round-trip"),
                );
                let again: Snapshot =
                    serde_json::from_value(encoded.clone()).expect("canonical Snapshot DTO");
                assert_eq!(
                    serde_json::to_value(again).unwrap(),
                    encoded,
                    "{id}/{index}: canonical Snapshot round-trip"
                );
                app.apply_snapshot(decoded, at);
            } else {
                let frame: ServerFrame =
                    serde_json::from_value(step["frame"].clone()).expect("Rust ServerFrame DTO");
                let encoded = serde_json::to_value(&frame).expect("serialize ServerFrame");
                subset(
                    &encoded,
                    &step["frame"],
                    &format!("{id}/{index}: wire round-trip"),
                );
                let again: ServerFrame =
                    serde_json::from_value(encoded.clone()).expect("canonical ServerFrame DTO");
                assert_eq!(
                    serde_json::to_value(again).unwrap(),
                    encoded,
                    "{id}/{index}: canonical ServerFrame round-trip"
                );
                assert!(
                    frame.id.is_none() && frame.result.is_none() && frame.error.is_none(),
                    "push-only frame"
                );
                app.apply_push(frame.push.expect("frame push"), at);
            }
            let expected = &step["expect"];
            let actual = observation(&app, &expected, at);
            subset(
                &actual,
                &expected,
                &format!("{id}/{index}: {}", step["reason"].as_str().expect("reason")),
            );
            total += 1;
        }
        cases += 1;
        println!("{id}: {} steps", steps.len());
    }
    assert!(cases > 0, "no cases supplied");
    println!(
        "Wire round-trip: {total} inputs, all supplied fields preserved; canonical DTOs equal"
    );
    println!("Rust DTO/TUI conformance: {cases} cases, {total} steps");
}
